import random, time

def with_retry(fn, max_attempts=5, base=0.5):
    for attempt in range(max_attempts):
        try:
            return fn()
        except TransientError:
            if attempt == max_attempts - 1:
                raise
            delay = base * (2 ** attempt) + random.uniform(0, 0.3)
            time.sleep(delay)
